/* Mobile 原型共享渲染：每个独立文件根据 data-page 呈现单一真实屏幕。 */
(function () {
  const page = document.body.dataset.page;
  const root = document.getElementById("app");
  if (!root || !page?.startsWith("mobile-")) return;

  function statusBar() {
    return `<div class="mobile-status" aria-label="设备状态"><span>9:41</span><span class="mobile-status-icons"><i data-lucide="signal"></i><i data-lucide="wifi"></i><i data-lucide="battery-full"></i></span></div>`;
  }
  function topbar(title, back = false, action = true) {
    return `<header class="mobile-topbar">${back ? '<button class="icon-btn" data-action="back" aria-label="返回"><i data-lucide="chevron-left"></i></button>' : `<h1>${title}</h1>`}${back ? `<h1 style="font-size:17px">${title}</h1>` : ""}<div style="display:flex;gap:6px">${action ? '<button class="icon-btn" data-action="theme" aria-label="切换主题"><i data-theme-icon data-lucide="sun"></i></button>' : ""}</div></header>`;
  }
  function bottomNav(active) {
    const items = [["home","总览","layout-dashboard"],["accounts","账户","wallet-cards"],["record","记一笔","plus"],["transactions","流水","list-filter"],["settings","我的","user-round"]];
    return `<nav class="mobile-bottom-nav" aria-label="底部导航">${items.map(([key,label,icon]) => key === "record" ? `<button class="mobile-nav-item primary" data-mobile-record data-od-id="mobile-record-entry"><i data-lucide="${icon}"></i><span>${label}</span></button>` : `<a class="mobile-nav-item ${active === key ? "active" : ""}" href="mobile-${key === "settings" ? "settings" : key}.html" ${active === key ? 'aria-current="page"' : ""}><i data-lucide="${icon}"></i><span>${label}</span></a>`).join("")}</nav>`;
  }
  function shell(content, active, title, options = {}) {
    return `<div class="mobile-stage"><main class="phone" data-od-id="mobile-${page.slice(7)}"><div class="mobile-app">${statusBar()}${topbar(title, options.back, options.action !== false)}${content}</div>${options.nav === false ? "" : bottomNav(active)}</main></div>`;
  }
  function mobileChart() { return `<div class="line-chart mobile-chart" role="img" aria-label="近30天净资产整体上升4.9%"><span class="axis-y"><span>84万</span><span>81万</span><span>78万</span></span><svg viewBox="0 0 360 130" preserveAspectRatio="none"><path d="M0,104 C30,100 45,83 70,91 S112,65 143,73 S181,91 211,68 S257,49 286,55 S330,27 360,32 L360,130 L0,130 Z" fill="var(--chart-fill)"/><path d="M0,104 C30,100 45,83 70,91 S112,65 143,73 S181,91 211,68 S257,49 286,55 S330,27 360,32" fill="none" stroke="var(--accent)" stroke-width="2.2" vector-effect="non-scaling-stroke"/><circle cx="360" cy="32" r="4" fill="var(--accent)"/></svg><span class="axis-x"><span>07/14</span><span>07/29</span><span>08/12</span></span></div>`; }
  function row(icon, title, sub, value, meta, href, cls = "") {
    const tag = href ? "a" : "button"; return `<${tag} class="mobile-row" ${href ? `href="${href}"` : ""}><span class="mobile-row-icon"><i data-lucide="${icon}"></i></span><span class="mobile-row-main"><strong>${title}</strong><span>${sub}</span></span><span class="mobile-row-value ${cls}">${value}<span>${meta}</span></span><i data-lucide="chevron-right"></i></${tag}>`;
  }

  function home() {
    // 总资产卡片本身是日历入口，保持单手可点击并提供明确文本。
    // 锁定的 Lucide 版本不含“云端勾选”名称，使用云图标并由文字明确表达成功语义。
    return shell(`<div class="mobile-content"><div class="sync-banner"><i data-lucide="cloud"></i><span>云端已同步，行情 20:30 更新</span></div><section class="mobile-hero"><div class="mobile-hero-label">净资产</div><div class="mobile-hero-value accent">¥826,432.18</div><div class="mobile-hero-delta">↗ 本月 +5.36%（+¥42,116.20）</div></section><section class="mobile-metrics"><a class="mobile-metric" href="mobile-asset-calendar.html"><span>总资产 · 日历</span><strong>¥982,760.44</strong></a><div class="mobile-metric"><span>总负债</span><strong>¥156,328.26</strong></div><div class="mobile-metric"><span>可用资金</span><strong>¥184,920.66</strong></div><div class="mobile-metric"><span>投资资产</span><strong>¥641,511.30</strong></div></section><section class="mobile-section"><div class="mobile-section-head"><h2>30 天趋势</h2><button>查看归因</button></div>${mobileChart()}<p class="field-help">文字摘要：工资与投资上涨是本月净资产增加的主要原因。</p></section><section class="mobile-section"><div class="mobile-section-head"><h2>数据质量</h2><a class="text-button" href="mobile-conflict.html">2 项需处理</a></div><div class="notice"><i data-lucide="triangle-alert"></i><div><strong>1 项同步冲突，2 只基金净值过期</strong><p>可继续记账，相关统计会标记为部分可用。</p></div></div></section><section class="mobile-section"><div class="mobile-section-head"><h2>近期流水</h2><a class="text-button" href="mobile-transactions.html">全部</a></div><div class="mobile-list">${row("shopping-basket","盒马鲜生","今天 19:26 / 餐饮","-¥286.40","招商银行 8286","mobile-transaction-detail.html","negative")}${row("landmark","华夏基金分红","今天 10:18 / 投资收益","+¥1,248.62","中信证券","mobile-transaction-detail.html","positive")}${row("undo-2","微信支付退款","昨天 21:02 / 退款","+¥68.00","微信零钱","mobile-transaction-detail.html","positive")}</div></section></div>`, "home", "总览");
  }
  function accounts() {
    return shell(`<div class="mobile-content"><section class="mobile-hero" style="padding-top:8px"><div class="mobile-hero-label">账户总额</div><div class="mobile-hero-value">¥982,760.44</div><div class="mobile-hero-delta" style="color:var(--muted)">8 个活跃账户 / 1 个归档账户</div></section><section class="mobile-section"><div class="mobile-section-head"><h2>现金账户</h2><span class="panel-sub">¥184,920.66</span></div><div class="mobile-list">${row("landmark","招商银行 8286","可用 ¥82,816.90","¥83,426.90","冻结 ¥610","mobile-account-detail.html")}${row("message-circle","微信零钱","电子钱包","¥6,218.42","全额可用","mobile-account-detail.html")}${row("users","家庭日常","共享 / 计入 60%","¥28,426.70","在途 ¥2,406.40","mobile-account-detail.html")}</div></section><section class="mobile-section"><div class="mobile-section-head"><h2>投资账户</h2><span class="panel-sub">¥641,511.30</span></div><div class="mobile-list">${row("chart-candlestick","中信证券","行情 20:30","¥438,621.10","现金 ¥31,820","mobile-account-detail.html")}${row("chart-pie","天天基金","净值已过期","¥202,890.20","08月09日","mobile-account-detail.html")}</div></section><section class="mobile-section"><div class="mobile-section-head"><h2>负债账户</h2><span class="panel-sub">¥156,328.26</span></div><div class="mobile-list">${row("credit-card","招商信用卡 6621","08月18日到期","-¥8,420.36","含利息 ¥36.20","mobile-account-detail.html","negative")}</div></section></div>`, "accounts", "账户");
  }
  function accountDetail() {
    return shell(`<div class="mobile-content"><section class="mobile-hero" style="padding-top:8px"><div class="mobile-hero-label">账面余额</div><div class="mobile-hero-value accent">¥83,426.90</div><div class="mobile-hero-delta" style="color:var(--muted)">可用 ¥82,816.90 / 冻结 ¥610.00</div></section><section class="mobile-section"><div class="mobile-section-head"><h2>余额变化</h2><span class="panel-sub">30 天</span></div>${mobileChart()}</section><section class="mobile-section"><div class="panel"><div class="quality-item"><div><strong>计入个人统计</strong><p>按 100% 计入后续统计</p></div><button class="switch" aria-checked="true" aria-label="计入个人统计"></button></div><div class="quality-item"><div><strong>共享成员</strong><p>林骁 OWNER，顾宜宁 VIEWER</p></div><i data-lucide="chevron-right"></i></div></div></section><section class="mobile-section"><div class="notice"><i data-lucide="info"></i><div><strong>账户口径</strong><p>修改个人计入比例不会重算历史数据。</p></div></div><button class="btn btn-danger" style="width:100%">归档账户</button></section></div>`, "accounts", "招商银行 8286", { back: true, nav: false });
  }
  function transactions() {
    return shell(`<div class="mobile-content"><div class="filter-search"><i data-lucide="search"></i><input class="input" placeholder="搜索交易或备注" aria-label="搜索流水"></div><div class="filterbar" style="margin-top:10px;flex-wrap:nowrap;overflow:auto"><button class="filter-chip active" data-filter="month">本月</button><button class="filter-chip" data-filter="account">账户</button><button class="filter-chip" data-filter="category">分类</button><button class="filter-chip" data-filter="type">类型</button></div><div class="mobile-section-head"><h2>今天</h2><span class="panel-sub">净流入 ¥1,030.22</span></div><div class="mobile-list">${row("shopping-basket","盒马鲜生","19:26 / 餐饮","-¥286.40","招商银行 8286","mobile-transaction-detail.html","negative")}${row("landmark","华夏基金分红","10:18 / 投资收益","+¥1,248.62","中信证券","mobile-transaction-detail.html","positive")}${row("train-front","地铁出行","08:42 / 交通","-¥6.00","支付宝","mobile-transaction-detail.html","negative")}</div><div class="mobile-section-head" style="margin-top:22px"><h2>昨天</h2><span class="panel-sub">净支出 ¥416.00</span></div><div class="mobile-list">${row("undo-2","微信支付退款","21:02 / 退款","+¥68.00","微信零钱","mobile-transaction-detail.html","positive")}${row("utensils","小满餐厅","18:46 / 餐饮","-¥484.00","家庭日常","mobile-transaction-detail.html","negative")}</div><div class="notice" style="margin-top:18px"><i data-lucide="history"></i><div><strong>更改可追溯</strong><p>修改或作废会保留历史记录并生成冲正记录。</p></div></div></div>`, "transactions", "流水");
  }
  function transactionDetail() {
    // 审计记录使用文件新增图标，和主操作的通用加号建立明确层级。
    return shell(`<div class="mobile-content"><section class="mobile-hero" style="text-align:center;padding-top:8px"><div class="mobile-hero-label">支出 / 已入账</div><div class="mobile-hero-value negative">-¥286.40</div><div class="mobile-hero-delta" style="color:var(--muted)">今天 19:26</div></section><section class="mobile-section"><div class="detail-grid panel"><div class="detail-cell"><span>付款账户</span><strong>招商银行 8286</strong></div><div class="detail-cell"><span>分类</span><strong>餐饮</strong></div><div class="detail-cell"><span>交易对方</span><strong>盒马鲜生</strong></div><div class="detail-cell"><span>标签</span><strong>家庭日常</strong></div></div></section><section class="mobile-section"><div class="section-title"><h3>审计记录</h3></div><div class="panel"><div class="quality-item"><span class="quality-icon"><i data-lucide="file-plus-2"></i></span><div><strong>创建交易</strong><p>林骁，今天 19:26</p></div><span class="badge">原始</span></div></div></section><section class="mobile-section"><button class="btn" style="width:100%;margin-bottom:8px">修改交易</button><button class="btn btn-danger" style="width:100%" data-action="void-transaction">作废交易</button><p class="field-help">作废后会生成金额相反的冲正记录。</p></section></div>`, "transactions", "流水详情", { back: true, nav: false });
  }
  function investments() {
    return shell(`<div class="mobile-content"><div class="sync-banner"><i data-lucide="database"></i><span>Tushare Pro / 股票行情 08月12日</span></div><section class="mobile-hero"><div class="mobile-hero-label">投资市值</div><div class="mobile-hero-value">¥641,511.30</div><div class="mobile-hero-delta">今日 +¥2,814.20 / +0.44%</div></section><a class="btn" style="width:100%;justify-content:center;margin-top:12px" href="mobile-investment-return-calendar.html"><i data-lucide="calendar-days"></i>查看投资收益日历</a><section class="mobile-metrics"><div class="mobile-metric"><span>未实现收益</span><strong class="positive">+¥47,209.12</strong></div><div class="mobile-metric"><span>已实现收益</span><strong>+¥18,406.80</strong></div></section><div class="notice" style="margin-top:16px"><i data-lucide="clock-3"></i><div><strong>2 只基金净值已过期</strong><p>可手工补录价格作为临时兜底。</p></div></div><section class="mobile-section"><div class="mobile-section-head"><h2>全部持仓</h2><span class="panel-sub">5 项</span></div><div class="mobile-list">${row("chart-no-axes-combined","沪深300ETF","510300 / ETF","¥184,620","+11.62%","mobile-investments.html","positive")}${row("chart-no-axes-combined","贵州茅台","600519 / 股票","¥167,528","+4.78%","mobile-investments.html","positive")}${row("chart-no-axes-combined","纳指ETF","513100 / ETF","¥126,473","+14.33%","mobile-investments.html","positive")}${row("clock-3","华夏回报混合A","净值 08月09日","¥92,890","+5.08%","mobile-investments.html","positive")}</div></section></div>`, "", "投资");
  }
  function settings() {
    return shell(`<div class="mobile-content"><section class="mobile-hero" style="display:flex;align-items:center;gap:14px"><span class="account-logo" style="width:48px;height:48px;border-radius:50%">林</span><div><div style="font:650 18px var(--font-display)">林骁</div><div class="panel-sub">linxiao@example.com</div></div></section><section class="mobile-section"><div class="mobile-list">${row("users","家庭成员","3 位成员 / 1 个邀请","","","mobile-settings.html")}${row("sun-moon","界面主题",document.documentElement.dataset.theme === "dark" ? "深色" : "浅色","","","mobile-settings.html")}${row("circle-dollar-sign","基准币种","人民币 CNY","","","mobile-settings.html")}${row("clock","时区","Asia/Shanghai","","","mobile-settings.html")}</div></section><section class="mobile-section"><div class="mobile-list">${row("shield-check","安全设置","密码与设备会话","","","mobile-settings.html")}${row("cloud","同步状态","刚刚同步","","","mobile-syncing.html")}</div></section><section class="mobile-section"><button class="btn btn-danger" style="width:100%">退出登录</button></section></div>`, "settings", "我的");
  }
  function auth() {
    return `<div class="mobile-stage"><main class="phone"><div class="mobile-app" style="padding-bottom:0">${statusBar()}<div class="mobile-content" style="display:flex;flex-direction:column;min-height:760px"><div class="brand" style="padding:18px 0"><span class="brand-mark">Z</span><span class="brand-name">资迹 <small>ZIJI</small></span></div><div style="margin:auto 0"><h1 style="margin:0;font:650 31px/1.12 var(--font-display);letter-spacing:-.05em">看清每一笔钱<br>现在在哪里。</h1><p style="color:var(--muted);margin:12px 0 28px">登录后继续查看资金全貌。</p><div class="tabs"><button class="tab active">登录</button><button class="tab">注册</button></div><form class="auth-form" style="margin-top:18px"><div class="field"><label>邮箱地址</label><input class="input" type="email" value="linxiao@example.com"></div><div class="field"><label>密码</label><input class="input" type="password" value="12345678"></div><button class="btn btn-primary" type="button" style="width:100%">登录</button><div class="auth-links"><span>仅支持邮箱登录</span><button type="button">忘记密码</button></div></form></div><p class="field-help" style="text-align:center">V1 不支持微信或手机号登录</p></div></div></main></div>`;
  }
  function state(kind) {
    const data = {
      offline: ["wifi-off","当前处于离线状态","仍可查看本地数据和继续记账。恢复网络后会将本地记录同步至云端。","继续离线使用","查看待同步记录","accent"],
      syncing: ["refresh-cw","正在同步 8 条记录","正在上传离线流水并校验账户余额，请保持应用开启。","后台继续","查看同步详情","accent"],
      conflict: ["git-compare-arrows","发现 1 项同步冲突","同一笔盒马鲜生交易在 iPhone 与云端被分别修改。请选择要保留的版本。","保留 iPhone 版本","保留云端版本","negative"],
      rejected: ["shield-x","操作被服务端拒绝","你对“家庭日常”账户只有 VIEWER 权限，不能新增或修改流水。","返回流水","联系 OWNER","negative"],
    }[kind];
    const extra = kind === "syncing" ? `<div class="progress" style="width:260px"><span style="width:64%"></span></div><p class="field-help">5 / 8 条已完成</p>` : kind === "conflict" ? `<div class="detail-grid panel" style="width:100%;margin-bottom:18px;text-align:left"><div class="detail-cell"><span>iPhone 离线版本</span><strong>¥286.40</strong></div><div class="detail-cell"><span>云端版本</span><strong>¥268.40</strong></div></div>` : "";
    return shell(`<div class="mobile-content state-screen"><div class="state-center"><div style="width:100%"><span class="state-icon" style="margin-inline:auto"><i data-lucide="${data[0]}"></i></span><h2>${data[1]}</h2><p>${data[2]}</p>${extra}<button class="btn btn-primary" style="width:100%;margin-bottom:8px" data-state-primary="${kind}">${data[3]}</button><button class="btn" style="width:100%">${data[4]}</button></div></div></div>`, "", kind === "conflict" ? "同步冲突" : "同步状态", { back: true, nav: false, action: false });
  }

  const screens = { "mobile-home": home, "mobile-accounts": accounts, "mobile-account-detail": accountDetail, "mobile-transactions": transactions, "mobile-transaction-detail": transactionDetail, "mobile-investments": investments, "mobile-settings": settings, "mobile-auth": auth, "mobile-offline": () => state("offline"), "mobile-syncing": () => state("syncing"), "mobile-conflict": () => state("conflict"), "mobile-rejected": () => state("rejected") };
  root.innerHTML = screens[page]?.() || "";
  window.Ziji?.refreshIcons();

  // 事件使用委托，保证 Bottom Sheet 内动态字段同样可操作。
  document.addEventListener("click", event => {
    if (event.target.closest("[data-mobile-record]")) window.Ziji?.makeOverlay("mobile-record-overlay", window.Ziji.recordDialog(true), false, true);
    if (event.target.closest('[data-action="back"]')) history.length > 1 ? history.back() : location.assign("mobile-home.html");
    if (event.target.closest('[data-action="void-transaction"]')) window.Ziji?.toast("交易已作废", "已保留原记录并创建冲正记录。");
    const primary = event.target.closest("[data-state-primary]");
    if (primary) {
      if (primary.dataset.statePrimary === "conflict") { window.Ziji?.toast("冲突已解决", "另一版本已保存到审计记录。"); setTimeout(() => location.assign("mobile-home.html"), 600); }
      else if (primary.dataset.statePrimary === "rejected") location.assign("mobile-transactions.html");
      else location.assign("mobile-home.html");
    }
  });
})();
